int bluetooth_get_sockaddr(struct socket *sock, struct sockaddr *addr, int *len, int peer) {
    struct sockaddr_l2 *l2addr = (struct sockaddr_l2 *)addr;

    l2addr->l2_family = AF_BLUETOOTH;
    if (peer) {
        l2addr->l2_bdaddr = sock->sk->sk_l2.dst;
        l2addr->l2_psm = sock->sk->sk_l2.dpsm;
    } else {
        l2addr->l2_bdaddr = sock->sk->sk_l2.src;
        l2addr->l2_psm = sock->sk->sk_l2.spsm;
    }

    *len = sizeof(struct sockaddr_l2);
    return 0;
}
